"""Original VUB lesson content. Run to regenerate the curriculum JSON."""
import json
from pathlib import Path
W=[]
def slide(title,body,kind='teach',**kw): return dict(title=title,body=body,kind=kind,**kw)
def add(n,title,summary,objectives,refs,agenda,slides,lab,answers):
 W.append(dict(n=n,title=title,summary=summary,objectives=objectives,refs=refs,agenda=agenda,slides=slides,lab=lab,answers=answers))
add(1,'Make technology work for you','Set up a comfortable workspace, organize a calendar, and solve everyday device problems.',
 ['Adjust device and browser settings for a task.','Create a practice appointment and choose what others can see.','Select a connection and a printer; verify the result.'],
 ['1.1','1.2','1.3','1.4','1.5','1.6','2.3'],
 [[10,'Welcome and goals','Ask which everyday task each learner wants to do more independently. Demonstrate text size and lesson navigation.'],[25,'Pre-test','Open the pre-test before instruction. Allow quiet work; read directions aloud without suggesting answers. Save or print each result.'],[20,'Model the setup','Teach slides on display, sound, browser settings, processing, cables and printing. Think aloud through one change and its check.'],[10,'Break','Offer a screen-free pause.'],[15,'Calendar and automation','Model a fictional appointment, free/busy sharing and an automation check. Play the explainer and pause for a prediction.'],[30,'Guided lab','Pairs complete the workstation and calendar worksheet. Partners switch driver and coach roles halfway.'],[10,'Check and transfer','Use both knowledge checks. Each learner demonstrates one adjustment, explains why it helps and restores the lab setting.']],
 [slide('Your starting point','Name a digital task you already do well. Choose one task you want to make easier.','discussion'),
 slide('Take the pre-test','This is a starting snapshot. Answer independently, then save or print your results.','assessment',href='pre'),
 slide('Change one setting; check the result','Decide what you need. Make one adjustment. Try the task again. Keep or undo the change.','steps',items=['Name the problem','Change one setting','Test and decide']),
 slide('Make text comfortable','Browser zoom changes a webpage. Display scaling changes the wider desktop. Start with the control that matches your problem.',refs=['1.1']),
 slide('Practice: zoom without losing your place','Use Ctrl and + to enlarge a page; Ctrl and - to reduce it; Ctrl and 0 to reset. On a Mac, use Command. Try this page’s text-size buttons too.','try'),
 slide('Sound and screen checks','Choose the correct speaker or headset before adjusting volume. Brightness changes light output; contrast changes separation between light and dark.',refs=['1.4']),
 slide('Browser choices belong to you','Review the home page, downloads location and site permissions in Settings. A helpful default should fit your task. Restore shared-lab settings before leaving.',refs=['1.1']),
 slide('Processing, storage, and connections','The processor carries out instructions. Memory holds current work. Storage keeps files. A matching connector shape alone does not guarantee every feature.',refs=['1.6']),
 slide('Match a connection to its job','Select each card to reveal a useful connection. Read the device label before buying or plugging in a cable.','flip',cards=[['An external display','HDMI commonly carries video and sound. USB-C video support depends on the device and cable.'],['A wired network','Ethernet connects a device to a network.'],['A keyboard or flash drive','USB carries data; USB-C also has charging and optional display uses.']]),
 slide('Printer choices','Laser printers use toner; inkjet printers use liquid ink. Choose for the task and running cost. A default printer is the device an app initially selects.',refs=['1.5']),
 slide('Print one page before twenty','Check the printer name and connection. Open print preview. Select one page, orientation and copies. Send a test page and check the output.','steps',items=['Confirm destination','Inspect preview','Print one test']),
 slide('A calendar entry needs enough detail','Create a fictional library visit: title, day, start and end, location and reminder. Check the time zone when an event involves another region.',refs=['1.2']),
 slide('Share availability thoughtfully','Free/busy can show when you are unavailable without the event’s private details. Verify the actual sharing options before inviting someone.',refs=['1.2']),
 slide('Switch the calendar view','Use day view for detail, week view for conflicts and month view for the larger picture. A task can have a due date without reserving meeting time.',refs=['1.2']),
 slide('Automation still needs a check','A rule can sort mail or repeat a reminder. Autocorrect changes likely mistakes; autocomplete suggests the rest. Review names, addresses and meaning before accepting.',refs=['1.3']),
 slide('Cloud services use another computer','Online storage and web apps use a provider’s computers over a network. Check account, connection and save status when you switch devices.',refs=['1.3']),
 slide('Watch: choose settings and verify','Follow the worked examples, pause for practice, and choose a chapter to replay a skill. Connect the task to a household or community situation you know.','video'),
 slide('Find help that fits your version','Use the app’s Help menu or official support. State the task, what you tried and the exact error. Ask a partner for one specific improvement.',refs=['2.3']),
 slide('Knowledge check: the wrong speaker','The video is playing silently. What should you check first?','check',options=['Buy a new monitor','Check output device and mute','Erase the browser history'],answer=1,why='The selected output device or mute setting may explain the silence. Change one thing and test.'),
 slide('Knowledge check: calendar privacy','A partner only needs to know when you are free. Which sharing option best fits?','check',options=['Show all event descriptions','Publish your account password','Share free/busy availability'],answer=2,why='Availability answers the scheduling question while limiting event details.'),
 slide('Lab: your usable workstation','Complete the worksheet. Show your partner the result of one setting change, a calendar entry and a print preview.','lab'),
 slide('Keep the routine','Choose a setting, test it and explain the result. Before leaving, save your practice work and restore shared settings.','summary')],
 ['Record one task you want to make easier and one skill you bring.','Increase webpage text. Record the control used and how to reset it.','Select the correct audio output; explain brightness versus contrast.','Match HDMI, Ethernet and USB to three tasks. Check one actual device port.','Create a fictional library appointment with a reminder. Record the fields you checked.','Choose a calendar view and a sharing level for a partner who only needs availability. Explain why.','Preview a one-page handout; record the printer, orientation and page range. Do not print unless the instructor directs it.','Type a sentence with a name that autocorrect changes. Correct it. Record a useful help search and one piece of partner feedback.'],
 ['Accept a personally meaningful goal and existing skill.','Browser zoom or site text-size control; demonstrate reset.','Check output and mute; brightness is light output, contrast is light/dark separation.','HDMI: display; Ethernet: network; USB: suitable peripheral. USB-C capabilities require checking.','Title, day, start/end, location, reminder; time zone when relevant.','Week for conflicts; free/busy for limited detail. Verify service-specific options.','The selected printer matches the lab destination; one-page preview prevents waste.','Learner reviews the result rather than trusting suggestions; help search names the app and task.'])
add(2,'Find, judge, and organize information','Find a reliable community resource and manage a shared file with care.',
 ['Refine a search and justify a source choice.','Complete a fictional online form and check its confirmation.','Organize files, set access and explain a recovery path.'],
 ['3.1','3.2','3.3','4.2','4.3.1','7.4'],
 [[10,'Reconnect','Ask learners to demonstrate last week’s check-one-change routine.'],[20,'Search demonstration','Teach keywords, filters and source evaluation with the supplied fictional source comparison.'],[20,'Research lab','Learners locate a public library service from an official source and record evidence. No account or application is needed.'],[10,'Break','Pause away from screens.'],[20,'Files demonstration','Teach forms, central storage, sync, access, compression and version history. Play the cloud-file explainer.'],[30,'Files lab','Use the practice form and sharing simulator, then organize a fictional folder. Complete the worksheet.'],[10,'Evidence check','Ask each learner to justify a source and a permission. Use the knowledge checks.']],
 [slide('Start with a question','You need a local library’s computer-help service. What information would make the answer usable?','discussion'),
 slide('Write a useful search','Include the service, place and audience. Try: public library computer help near your town. Remove words that distract from the task.',refs=['3.1']),
 slide('Refine without hiding useful results','Use the search tool’s date or content filters when they fit. Quotation marks can narrow an exact phrase. A site: filter narrows a domain, but does not prove accuracy.',refs=['3.1']),
 slide('Five questions for a source','Who made it? What evidence supports it? What perspective or interest shapes it? Is it current enough? Does it answer this task?','steps',items=['Check author and evidence','Check purpose and currency','Check fit and corroboration'],refs=['3.2']),
 slide('Compare two results','These are fictional practice sources. Select a card, then justify which source you would verify first.','flip',cards=[['Library service page','Named library, contact method, service hours and update note. Verify details through its official contact.'],['Unattributed social post','No author or date; promises every service is free everywhere. Treat the claim as unverified.']]),
 slide('Accuracy and relevance differ','A correct article about a library in another state may not answer a local question. A recent page can still be biased or wrong. Check more than one signal.',refs=['3.2']),
 slide('Keep a source trail','Record title, organization, URL, access date and the specific detail you used. Separate a direct quotation from your own summary.',refs=['3.1','4.3.1']),
 slide('Collect only what the task needs','Forms and surveys collect responses into a shared system. Identify who collects the data, why, and which fields are required before typing.',refs=['3.3']),
 slide('Practice form: request computer help','Use fictional details in this local practice form. Check required fields, review your choices and read the confirmation.','form',refs=['3.3']),
 slide('Name files so you can find them','Use a clear subject and version: library-resource-v1.docx. Put related files in one folder. Avoid names such as final-final-new.',refs=['4.2']),
 slide('Central storage needs clear access','A shared drive keeps a common copy in one place. The service, account or organization controls access and retention. A shared link does not transfer ownership.',refs=['3.3','4.2']),
 slide('Sync, backup, and recovery','Sync carries changes, including some deletions, between locations. A separate backup provides another recovery path. Version history may recover earlier content.',refs=['4.2']),
 slide('Watch: search, judge, share, recover','Follow the worked examples, pause for practice, and choose a chapter to replay a skill. Connect the task to a household or community situation you know.','video'),
 slide('Choose who can change the file','A viewer reads. A commenter suggests, where supported. An editor changes content. Limit access to the named people who need it.','permissions',refs=['4.2','7.4']),
 slide('Read-only is not encryption','Read-only and editing restrictions limit changes. Encryption protects readable content with a key. Password-to-open and password-to-edit can protect different things.',refs=['4.2','7.4']),
 slide('Compression packages files','A ZIP archive can bundle files and sometimes reduce size. Extract it before editing. Images and video may already be compressed. A ZIP file is not automatically encrypted.',refs=['4.2']),
 slide('Recover the right thing','Deleted file? Check trash or recycle bin. Wrong content? Inspect version history. Preview first and coordinate with collaborators before restoring.',refs=['4.2']),
 slide('Knowledge check: a credible page','Which action best checks a surprising service claim?','check',options=['Trust the first result','Count the page’s colors','Verify it with the responsible organization'],answer=2,why='A responsible primary source and corroborating evidence are stronger than ranking or appearance.'),
 slide('Knowledge check: read-only','A file is read-only. What does that tell you?','check',options=['Editing is restricted','The content is encrypted','Nobody can copy the content'],answer=0,why='Read-only describes an editing restriction. It does not by itself prove confidentiality or prevent copying.'),
 slide('Lab: build a resource folder','Find one useful source, record the evidence, organize a fictional file and demonstrate a limited share.','lab'),
 slide('Your repeatable information routine','Ask a clear question, check the source, save the evidence and limit access.','summary')],
 ['Write a focused question about a local public service.','Record an initial search and one refinement or filter. Explain its effect.','Record a source title, organization, URL, access date and useful detail.','Judge the source’s accuracy, perspective, bias, credibility and relevance. Name one check still needed.','Complete the fictional practice form. Record a validation message and the confirmation.','Create a folder and clear filename. Describe who controls a cloud copy.','Choose permissions for a reader, a reviewer and a coauthor. Demonstrate one in the simulator.','Explain when to use version history, a recycle bin or a backup. Explain why ZIP and read-only do not prove encryption.'],
 ['Question identifies a service and location.','Refinement narrows the actual need without treating ranking as proof.','All five source fields are recorded; details use no personal records.','Evidence-based judgments, including an uncertainty or direct verification step.','Missing required choice is corrected; confirmation does not claim a real request was sent.','Meaningful name and folder; account/service or organization controls access.','Viewer, commenter when available, editor; named recipients and least useful access.','History: earlier content; trash: deleted file; backup: separate recovery copy. ZIP bundles; read-only restricts editing.'])
add(3,'Create something people can use','Build a clear resource handout, a small workbook, and a short presentation.',
 ['Structure a document for reading and revision.','Use a formula and format a small workbook.','Adapt a presentation and media for an audience and credit reused work.'],
 ['4.1','4.2','4.3','4.4'],
 [[10,'Retrieve','Review last week’s source trail and folder choices.'],[20,'Document model','Demonstrate heading styles, lists, shortcuts, track changes and a reviewed export.'],[20,'Document lab','Learners create a one-page fictional community resource handout; partners suggest and review one edit.'],[10,'Break','Offer a posture and screen break.'],[20,'Workbook and media model','Demonstrate the supplied CSV, SUM, units, a simple chart, cropping, trimming and captions. Play the explainer.'],[30,'Creation lab','Learners finish the workbook and three-slide presentation using worksheet requirements.'],[10,'Show and explain','Peer review for readability, accuracy, credit and appropriate file format. Use knowledge checks.']],
 [slide('Create for someone specific','Your audience is a neighbor looking for computer help. What would they need first, and what can you leave out?','discussion'),
 slide('A document needs structure','Use a descriptive title, real heading styles, short sections and a list of steps. Bold alone does not create a heading for assistive technology.',refs=['4.1']),
 slide('Keyboard shortcuts with a purpose','Ctrl+C copies; Ctrl+V pastes; Ctrl+Z undoes; Ctrl+S saves. On a Mac, use Command. Practice selecting only the text you want to change.',refs=['4.1']),
 slide('Make one clear paragraph','State the service, who it helps and the next action. Read it aloud. Replace vague words with concrete instructions.',refs=['4.1','4.4']),
 slide('Track a proposed change','Turn on Track Changes or Suggesting in your editor. Make one edit. The reviewer accepts or rejects it; a comment can explain why.',refs=['4.1']),
 slide('Prepare a handout someone can read','Use real headings, readable type and meaningful link text. Add useful alternative text to informative images. Do not rely on color alone.',refs=['4.1','4.4']),
 slide('A workbook has rows, columns, and cells','A row can represent one item; a column can represent a category. Label the units. Keep numbers as numbers so formulas can calculate.',refs=['4.1']),
 slide('Build a fictional supply budget','Enter Paper: 12, Folders: 8, Pens: 5 in a cost column. In a total cell, use =SUM(B2:B4). The expected total is 25.','spreadsheet',refs=['4.1']),
 slide('Check the formula, not just the appearance','Change the paper cost to 15. The total should become 28. If it does not, check the cell range and whether values were entered as text.','try'),
 slide('A chart answers a question','A bar chart can compare costs. Use a title and labels with units. Keep a readable data table so the numbers are available without interpreting color.',refs=['4.1']),
 slide('Three slides; one useful message','Slide 1: the need. Slide 2: the steps. Slide 3: where to get help. Use one consistent theme and enough contrast for the room.',refs=['4.1','4.3','4.4']),
 slide('Crop, resize, and preserve the original','Crop removes outer areas. Resize changes dimensions. Save a copy before editing. Do not stretch an image or remove a creator’s credit.',refs=['4.1']),
 slide('Basic video editing','Trim an unwanted start or end. Split to remove a middle section. Arrange clips, balance speech volume and add accurate captions. Check the exported result.',refs=['4.1']),
 slide('Watch: create, check, and export','Follow the worked examples, pause for practice, and choose a chapter to replay a skill. Connect the task to a household or community situation you know.','video'),
 slide('Reusing content requires permission','Check the license and its conditions. Credit the creator, title, source and license when required. An image appearing in search does not mean you may reuse it.',refs=['4.3']),
 slide('Choose a format for the next person','An editable document supports revision. PDF preserves a finished layout. CSV carries simple table data but loses formatting and formulas.','flip',cards=[['A neighbor needs a handout','PDF, then check reading order and legibility.'],['A partner must edit paragraphs','An editable document with appropriate access.'],['A tool needs plain rows and columns','CSV; verify dates, separators and lost formatting.']],refs=['4.4']),
 slide('Inspect the export','Open the exported file. Check headings, page breaks, links and missing content. Verify the filename and folder. The export is a separate artifact to test.',refs=['4.4']),
 slide('Knowledge check: a changing total','Which formula adds values from B2 through B4?','check',options=['=SUM(B2:B4)','=B2+B4','=SUM(A1:A2)'],answer=0,why='B2:B4 includes B2, B3 and B4. Check by changing one input.'),
 slide('Knowledge check: a proposed edit','You want the owner to decide whether to keep your wording. What should you use?','check',options=['Delete their document','Track Changes or Suggesting','Make a screenshot'],answer=1,why='Tracked or suggested edits preserve the review decision for the owner.'),
 slide('Lab: your resource pack','Create a handout, a checked workbook and a three-slide explanation. Use the supplied original image or an appropriately licensed alternative.','lab'),
 slide('Useful beats elaborate','A clear structure, a correct calculation and a tested export serve your audience.','summary')],
 ['Identify the audience and action for a fictional computer-help handout.','Create a document with a title, two heading styles, a short paragraph, a numbered list and a meaningful link.','Use copy, paste and undo; record one place a shortcut helped.','Suggest or track one partner edit, then accept or reject it with a reason.','Open supplies.csv in a spreadsheet. Add =SUM(B2:B4); verify 25, then change paper to 15 and verify 28.','Build three slides: need, steps, help. Use one theme, readable type, useful image alt text and a data table or labeled chart.','Crop a copy of the supplied original image. Describe trimming, splitting and captions for a short video. Record any source and license.','Export the handout to PDF and reopen it. Record two checks, and explain when editable format or CSV would be better.'],
 ['A specific neighbor/audience and a clear next action.','Semantic heading styles, concise task-focused copy and descriptive link.','Demonstrates selection and successful undo without losing work.','Revision remains reviewable; accepts/rejects deliberately.','Correct range, numeric cells and recalculated 28.','One message per slide, consistent theme, non-color cues and useful text alternatives.','Original preserved; crop differs from resize; trim removes edges, split isolates middle, captions convey speech.','Checks content/links/layout; editable supports revision, CSV carries plain data.'])
add(4,'Communicate and collaborate with care','Choose the right channel, give useful feedback, and make safe online choices.',
 ['Choose a communication channel and write a clear email.','Collaborate using comments, coauthoring and version history.','Explain online purchases, subscriptions and digital identities.'],
 ['2.1','2.2','2.3','5.1','5.2','6.1','6.2'],
 [[10,'Reconnect','Share one improvement from the resource-pack review.'],[20,'Communication model','Demonstrate audience, timing, identity, email fields and channel choice.'],[20,'Message lab','Pairs draft a fictional request and revise for clarity and inclusive language.'],[10,'Break','Pause away from screens.'],[20,'Collaboration and commerce','Demonstrate coauthoring, comments, meeting controls and purchase review; play the explainer.'],[30,'Team lab','Complete the shared-document role play and fictional subscription comparison. Switch roles.'],[10,'Check and reflect','Use knowledge checks and ask each learner to describe one helpful feedback habit.']],
 [slide('Choose a channel for the task','A quick status update, a detailed request and an urgent issue may need different channels. Consider the audience, sensitivity and response time.','discussion',refs=['5.1']),
 slide('Personal and professional identities','Use the account and tone appropriate to the role. Check the active account before posting. Separate credentials; use a trusted password manager and multifactor authentication where available.',refs=['2.1']),
 slide('Write an email someone can act on','Use a specific subject, a greeting, one clear request, needed context and a courteous close. Check the recipient and attachment before sending.',refs=['5.1']),
 slide('To, Cc, and Bcc','To names the main recipient. Cc keeps others visibly informed. Bcc hides that recipient list from other recipients; it does not encrypt the message.',refs=['5.1']),
 slide('Timing changes how a message lands','Check urgency and working hours. State when a response is needed. Scheduled send can help, but verify its settings and your wording first.',refs=['2.2']),
 slide('Inclusive language helps people respond','Use the name and form of address people prefer. Explain unfamiliar abbreviations. Avoid assumptions about age, culture, abilities or technology experience.',refs=['2.2','5.1']),
 slide('Participate in a community','Read the group’s guidelines, stay on topic and disagree with ideas respectfully. Ask permission before sharing someone else’s story or image.',refs=['5.1']),
 slide('Verify a community service','Use an organization’s official contact or website to confirm eligibility, availability and hours. A directory entry is a starting point; details can change.',refs=['5.1']),
 slide('Collaborate on one shared copy','Assign an owner, writer and reviewer. Agree on where the file lives and what finished means. Clear roles reduce conflicting edits.',refs=['6.1']),
 slide('Live editing or later feedback?','Synchronous work happens together. Asynchronous work happens at different times. Match the method to schedules and the decision needed.','flip',cards=[['Write together during class','Synchronous coauthoring: coordinate who edits which section.'],['Review after class','Asynchronous comments: include enough context for the writer.']],refs=['6.1']),
 slide('Feedback names an improvement','Try: “The contact method is hard to find. Could we put it after the steps?” Be specific about the text, reason and possible change.',refs=['6.1','2.3']),
 slide('Acknowledge and resolve','Read a comment, ask if unclear, make or decline the change with a reason, then resolve it. Use version history if a useful edit is lost.',refs=['6.1']),
 slide('Meetings and webinars','Test sound. Mute when not speaking. Use raise-hand or chat as directed. Ask before recording. A webinar usually gives hosts more control than a small meeting.',refs=['6.2']),
 slide('Watch: collaborate without confusion','Follow the worked examples, pause for practice, and choose a chapter to replay a skill. Connect the task to a household or community situation you know.','video'),
 slide('Goods, services, and subscriptions','Goods are products; services provide work or access. Streaming delivers media over a connection. A subscription can renew until canceled.',refs=['5.2']),
 slide('Review a digital payment','A payment service sends an authorized payment request. Check seller, total, recurring terms, delivery and refund information. A familiar logo alone does not verify a seller.',refs=['5.2']),
 slide('Small in-app purchases add up','A download may be free while features cost money. Review purchase controls and receipts. Do not authorize a real purchase during this activity.',refs=['5.2']),
 slide('Knowledge check: useful feedback','Which comment best supports revision?','check',options=['This is bad.','I dislike everything.','Add the contact number after the steps so readers can find help.'],answer=2,why='It identifies a specific change and explains its value to readers.'),
 slide('Knowledge check: a trial offer','Before starting a free trial, what should you check?','check',options=['Renewal price, renewal timing and cancellation terms','Only the button color','Whether the site has animations'],answer=0,why='The full terms determine whether the trial becomes a recurring charge.'),
 slide('Lab: coordinate a small team','Draft a fictional message, review a partner’s document and compare the supplied fictional offers.','lab'),
 slide('Leave a clear next step','A useful message says who needs to do what and when. A useful review helps the next person act.','summary')],
 ['Choose a channel for a detailed nonurgent request and for an urgent lab problem. Explain the difference.','Draft an email to a fictional library helper: subject, request, context and close. Do not send it.','Explain To, Cc and Bcc. Choose an appropriate time and account for your message.','Revise one sentence to remove an assumption or unexplained abbreviation.','Assign owner, writer and reviewer roles. Choose live coauthoring or later comments and justify access.','Write a specific comment on the resource handout. Respond, revise and record the decision.','List four meeting or webinar habits, including recording consent.','Compare fictional offer A: $5 monthly, cancel before renewal; offer B: $48 yearly, renews annually. Calculate one year of A ($60) and list questions before authorizing either.'],
 ['Email for detailed nonurgent context; direct instructor conversation for urgent local issue.','Specific subject, clear request, sufficient context, correct recipient and courteous close.','To primary; Cc visible others; Bcc concealed recipient list, not encryption. Work hours/urgency and right identity.','Respectful specific language with no age/culture/ability assumptions.','Roles and permission fit; synchronous together or asynchronous across time.','Specific change plus reason; reviewer decision recorded.','Audio test, mute/raise hand, useful chat, consent before recording.','$60 versus $48 nominal year; also compare needs, features, refunds, renewal and cancellation. No real transaction.'])
add(5,'Protect your work and show your skills','Practice safe decisions, complete a skills challenge, and measure your growth.',
 ['Explain device, file and account protections.','Recognize manipulation and choose a safe next step.','Demonstrate core tasks and complete the parallel post-test.'],
 ['7.1','7.2','7.3','7.4','2.1','4.2'],
 [[10,'Retrieve and preview','Ask learners to name a source check, a file permission and a useful feedback habit.'],[20,'Safety model','Teach ergonomics, universal design, manipulation, encryption, unknown media and camera permissions.'],[15,'Scenario practice','Use the flip cards and explainer. Learners state the evidence and safest next step.'],[10,'Break','Take a screen-free break.'],[25,'Performance challenge','Learners demonstrate the core tasks on the worksheet. Instructor records independent, prompted or needs practice.'],[25,'Post-test','Complete the parallel assessment independently. Enter the saved pre-test score only if the learner wants a comparison. Print or save results.'],[15,'Review and next steps','Discuss explanations after submission. Choose a practice priority without treating the classroom score as certification.']],
 [slide('Safety is a set of decisions','Choose one habit that protects your work and one that helps you use technology comfortably.','discussion'),
 slide('A comfortable workstation','Place the screen where you can read without strain. Support your posture, take breaks and adjust input devices to your needs. Ask for help with persistent discomfort.',refs=['7.1']),
 slide('Universal design helps more people','Captions, readable controls and flexible input methods make tools usable in more situations. Keyboard access helps people who cannot use a mouse.',refs=['7.1']),
 slide('Protect attention and wellbeing','Frequent alerts and comparison can create pressure. FOMO means fear of missing out. Adjust notifications and choose a stopping point.',refs=['7.2']),
 slide('An online identity can be invented','Catfishing uses a false identity to build trust. Pressure for money, secrecy or personal information is a reason to pause and verify independently.',refs=['7.2']),
 slide('Respond to harmful posts','Avoid escalating. Preserve evidence when safe, use reporting or blocking tools and seek support. Negative posts can affect real relationships and future opportunities.',refs=['7.2']),
 slide('An urgent message is not proof','Unexpected threats or rewards may be phishing. Avoid the supplied link. Contact the organization through a known website or number.',refs=['7.1']),
 slide('Choose a safer next step','Select a scenario to reveal a response. Explain what evidence would change your decision.','flip',cards=[['An unknown USB drive is on the desk','Do not connect it. Give it to the instructor or authorized support.'],['A calculator site asks for camera access','Deny it unless the task has a clear, trusted need.'],['A message demands payment to keep benefits','Pause. Verify through the organization’s known contact; do not use the message’s link.']]),
 slide('Encryption protects readable data','Encryption scrambles data so a key is needed to read it. Device encryption can protect a lost powered-off device; an unlocked signed-in session still needs protection.',refs=['7.3']),
 slide('Passwords protect different actions','Some file passwords control opening; others restrict editing. Check which protection is enabled and how recovery works. Avoid storing the password beside the protected file.',refs=['7.4']),
 slide('Unknown devices can carry risk','Portable storage may contain malicious software. Use approved devices and follow lab procedures. Do not plug in unknown media to find its owner.',refs=['7.3']),
 slide('Control camera and microphone access','Allow access only when the task needs it and you trust the app. Review permissions after a meeting. Block requests unrelated to what you are doing.',refs=['7.3']),
 slide('Watch: pause, verify, protect','Follow the worked examples, pause for practice, and choose a chapter to replay a skill. Connect the task to a household or community situation you know.','video'),
 slide('Practice the whole routine','Find a source, create a useful file, limit access and explain a recovery choice. Use fictional information.','lab'),
 slide('Knowledge check: encryption','What is encryption designed to do?','check',options=['Make a file smaller','Require a key to read scrambled data','Make every message trustworthy'],answer=1,why='Encryption protects readability. It does not make the source trustworthy or replace access controls.'),
 slide('Knowledge check: camera access','A simple text webpage asks to use your camera. What is a sensible response?','check',options=['Always allow every request','Share your password instead','Deny access when it is not needed for the task'],answer=2,why='Permission should fit a clear purpose. An unrelated request can be denied.'),
 slide('Take the post-test','Complete the questions independently. Save or print the graded results, including explanations and your practice priorities.','assessment',href='post'),
 slide('Read your results as a learning plan','Look at domain scores and missed questions. Choose one task to practice next. These classroom checks do not award IC3 certification.','summary')],
 ['Adjust one workstation feature and explain the need it addresses.','Define universal design and name two useful examples.','For an urgent suspicious message, write an independent verification plan.','Explain catfishing, FOMO and a constructive response to harmful posts.','Choose responses to unknown USB media and an unnecessary camera request.','Explain device encryption, a file password and editing restrictions without treating them as identical.','Performance challenge: refine a public-service search; justify a source; create a structured paragraph; calculate a three-item total; choose sharing access; give useful feedback; name a recovery method.','Save or print your post-test results. Identify one strength and one next practice task.'],
 ['An appropriate comfort adjustment and observable benefit; avoid diagnostic claims.','Usability for diverse people/situations; captions and keyboard controls are examples.','Do not use supplied link; find official contact independently.','False identity; fear of missing out; document/report/block/seek support as appropriate.','Do not connect unknown media; deny permissions without a task-related need.','Encryption needs a key; passwords can protect opening or editing; read-only does not prove encryption.','Mark each of seven tasks Independent / With prompt / Needs practice; keep performance separate from quiz score.','Result preserved by learner; specific task linked to a domain that needs practice.'])
add(6,'Build a small web app with AI','Turn a clear need into a tested, accessible prototype using basic vibe coding.',
 ['Describe a small app and write a bounded AI prompt.','Explain HTML, CSS, JavaScript and browser storage.','Test a prototype, revise one behavior and explain what a hosted service still needs.'],
 ['Extension: basic web app and SaaS prototyping'],
 [[10,'Choose the problem','Introduce a fictional community-resource finder and agree on three observable requirements.'],[20,'Model a first build','Explain website versus web app versus SaaS. Demonstrate the supplied starter and a bounded AI prompt; no paid account is required.'],[20,'Build round one','Learners use an approved AI tool or edit the supplied starter. Save a first version before changes.'],[10,'Break','Pause away from screens.'],[15,'Test demonstration','Play the explainer; show keyboard, empty-result, narrow-screen and privacy checks.'],[30,'Improve and retest','Pairs swap tester/builder roles, fix one observed defect and record evidence.'],[15,'Demo and reflection','Demonstrate three acceptance checks and complete the extension rubric. Discuss hosting requirements without deploying.']],
 [slide('Solve one small problem','Build a finder for fictional community resources. A visitor should be able to search, filter and understand the results.','discussion'),
 slide('Website, web app, and SaaS','A website presents pages. A web app adds interactive tasks. SaaS is software operated as an ongoing online service; it may need accounts, shared storage, support and maintenance.'),
 slide('Vibe coding starts with clear instructions','Describe the result you want in ordinary language, ask AI to produce code, then inspect and test what it gives you. You are responsible for the result.'),
 slide('Three parts of a browser app','HTML gives content structure. CSS controls appearance. JavaScript responds to input. A server can add shared data and protected operations.','flip',cards=[['A labeled search field','HTML provides the input and its label.'],['A readable narrow-screen layout','CSS arranges content and styles focus.'],['Filtering the resource list','JavaScript updates results after user input.']]),
 slide('Write acceptance checks first','Search finds the named fictional service. The keyboard reaches every control. An unmatched search explains that no results were found.','steps',items=['Name one user task','Write three observable checks','Use fictional data']),
 slide('A prompt with useful boundaries','Build one HTML file for a fictional resource finder. Include a labeled search field, category filter and readable results. Use semantic buttons, visible focus and no external dependencies. Do not collect personal data.','prompt'),
 slide('Ask the AI to explain its work','Ask where the data lives, what each file does, and how to test the three requirements. Treat the explanation as a claim to verify against behavior.'),
 slide('Start with a working reference','Open the supplied starter app and complete all three checks. Download the editable HTML file and save a copy before making a change.','starter'),
 slide('No AI account? You can still build','Edit the supplied HTML in a plain-text editor. Change the heading and one fictional resource, save, then reopen the file. Use the worksheet’s exact edit steps.','try'),
 slide('Make one change at a time','Save version 1. Ask for a small change. Review the difference. Test again. Restore version 1 if the change breaks a requirement.'),
 slide('A useful revision request','The filter works with a mouse but the focus is hard to see. Add a clear focus outline to all controls. Keep existing search behavior and fictional data.'),
 slide('Where does the data live?','A JavaScript array is bundled with the page. Browser storage belongs to that browser and can be cleared. A shared database supports cross-device data and requires access controls.'),
 slide('Keep secrets out of browser code','Anything shipped to a browser can be inspected. Do not put API keys, passwords or private records in HTML or JavaScript. Use fictional records for this prototype.'),
 slide('A mock sign-in is not security','A login-looking screen does not protect data by itself. Real accounts need server-side authorization, safe credential handling and tested access rules.'),
 slide('Watch: prompt, test, revise','Follow the worked examples, pause for practice, and choose a chapter to replay a skill. Connect the task to a household or community situation you know.','video'),
 slide('Test more than the happy path','Try blank search, no match, mixed-case search, category changes, narrow screen and keyboard-only use. Record expected and actual results.','steps',items=['Normal task','Empty and unexpected input','Keyboard and small screen']),
 slide('Fix what you can demonstrate','Describe steps, expected result and actual result. Ask for a focused correction. Repeat the failed test and a previously passing test.'),
 slide('Hosting is a separate decision','A local file is visible on your computer. Hosting makes it reachable online. Before a real launch, review content rights, access, data handling, costs, backups and who maintains it.'),
 slide('Knowledge check: AI confidence','The AI says the app is fully tested. What should you do?','check',options=['Run the acceptance checks yourself','Skip testing','Add real personal records immediately'],answer=0,why='An AI statement does not replace observed behavior and recorded results.'),
 slide('Knowledge check: a secret key','Where should a private API key go in a browser prototype?','check',options=['In a hidden HTML comment','In a public JavaScript variable','Nowhere in the browser code'],answer=2,why='Browser code is inspectable. Protected secrets belong in an appropriate server-side design.'),
 slide('Lab: build, test, explain','Demonstrate your app, one revision and your test log. Explain one limitation before this could become a real service.','lab'),
 slide('You can direct a build and judge it','Keep the prompt, source file, test log and next step. Clear requirements and careful checks remain useful as tools change.','summary')],
 ['Name the app’s user, problem and three acceptance checks. Keep the scope to one page.','Write a prompt naming content, behavior, accessibility and privacy boundaries.','Open the starter. Save a copy as resource-finder-v1.html using a plain-text editor. If working offline, no AI tool is required.','Find the <h1> heading in the source and replace only its text. In the resources array, change the fictional Library Skills Desk name to Community Skills Desk. Save as resource-finder-v2.html and reopen.','Ask an approved AI tool for one small improvement, or make the heading/data edit manually. Record exactly what changed.','Test blank input, matching and nonmatching search, mixed case, category filters, keyboard focus and narrow-screen layout. Record expected, actual and pass/fail.','Fix one defect or improve one requirement. Repeat its test and one previously passing test. Keep both versions.','Demonstrate the app. Explain HTML/CSS/JavaScript, where data lives, and why a public SaaS service needs additional design and maintenance.'],
 ['One specific user task and three observable outcomes.','Bounded one-file app; no personal data, secrets, payments or external dependencies.','Both original and working copy retained; .html extension, not rich text or .txt.','Heading changes visibly; new fictional name appears and is searchable. Quotes, commas and tags stay intact.','Revision small enough to explain; no unsupported claims about AI correctness.','All seven paths tested; honest failures and expected/actual evidence recorded.','Failed path now works or limitation clearly documented; regression check still passes.','HTML structure, CSS appearance, JavaScript behavior; in-page sample data, no protected backend; launch needs further checks.'])
